from collections import Counter
def transform(g):
    h,w=len(g),len(g[0]); r=[row[:] for row in g]
    glob=Counter(c for row in g for c in row).most_common(1)[0][0]
    for i in range(h):
        for j in range(w):
            ns=[g[y][x] for y,x in ((i-1,j),(i+1,j),(i,j-1),(i,j+1)) if 0<=y<h and 0<=x<w]
            if ns and g[i][j] not in ns:
                cnt=Counter(ns); best=max(cnt.values())
                cand=[c for c in cnt if cnt[c]==best]
                r[i][j]=cand[0] if len(cand)==1 else next(c for c in cand if c!=glob)
    return r
